/* Dated public polling research. No predictions or voter targeting. */
'use strict';
(() => {
  const target = document.getElementById('polling-research');
  if (!target || document.getElementById('senate-research')) return;
  const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const date = value => new Date(value + 'T12:00:00Z').toLocaleDateString('en-US', {month:'long',day:'numeric',year:'numeric',timeZone:'UTC'});
  const period = p => date(p.field_start) + ' to ' + date(p.field_end);
  const link = (url, label) => `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
  const section = document.createElement('section');
  section.id = 'senate-research'; section.className = 'section';
  section.setAttribute('aria-labelledby', 'senate-title');
  section.innerHTML = '<p class="eyebrow">03A / SENATE SURVEY RESEARCH</p><h2 id="senate-title">Louisiana’s U.S. Senate race</h2><p id="senate-status" role="status">Loading the dated Senate research collection.</p>';
  target.before(section);
  const style = document.createElement('style');
  style.textContent = `
#senate-research{scroll-margin-top:90px;color:#182c47}#senate-research *{box-sizing:border-box}#senate-research [hidden]{display:none!important}#senate-research h2{font-size:clamp(28px,4vw,42px);line-height:1.15;margin:8px 0 14px}#senate-research h3{font-size:23px;line-height:1.25;margin:0 0 12px}#senate-research h4{font-size:17px;margin:20px 0 8px}#senate-research p{line-height:1.6}#senate-research .sr-fine{font-size:14px;line-height:1.55;color:#4c6177}#senate-research .sr-badge{display:inline-block;font-size:12px;font-weight:700;border-radius:5px;background:#e9eff6;padding:6px 9px;margin:0 5px 8px 0}#senate-research .sr-sponsor{background:#fff1d9;color:#704614}#senate-research .sr-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}#senate-research .sr-button{font-family:inherit;font-size:15px;font-weight:600;line-height:1.35;min-height:44px;padding:10px 14px;border:1px solid #b9c8d9;border-radius:7px;background:#fff;color:#173e65;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}#senate-research .sr-tabs [aria-selected=true]{color:#fff;background:#173e65;border-color:#173e65}#senate-research .sr-grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:22px}#senate-research .sr-card{padding:24px;background:#fff;border:1px solid #d0dce8;border-radius:13px;min-width:0}#senate-research .sr-subtle{background:#f5f8fc}#senate-research .sr-callout{border-left:4px solid #397787;padding:14px 18px;background:#edf5f7;margin:18px 0;font-size:15px;line-height:1.6}#senate-research .sr-callout p{margin:0}#senate-research .sr-warning{background:#fff5e6;border-color:#b57927}#senate-research label{display:block;font-weight:700;margin-bottom:7px}#senate-research select{width:100%;min-height:46px;font:inherit;background:#fff;color:#182c47;border:1px solid #a8bad0;border-radius:7px;padding:10px;margin-bottom:20px}#senate-research .sr-bar{margin:17px 0}#senate-research .sr-bar-label{display:flex;justify-content:space-between;gap:12px;line-height:1.4;font-size:16px;margin-bottom:8px}#senate-research .sr-bar-label strong{font-size:23px}#senate-research .sr-track{height:18px;background:#e9eef4;border-radius:4px;overflow:hidden}#senate-research .sr-fill{display:block;height:100%}#senate-research .sr-dem{background:#2563eb}#senate-research .sr-rep{background:#d92d3a}#senate-research .sr-other{background:#738197}#senate-research .sr-axis{display:flex;justify-content:space-between;font-size:12px;color:#4c6177;margin:8px 0 18px}#senate-research .sr-meta{margin:0}#senate-research .sr-meta div{border-bottom:1px solid #dce5ee;padding:10px 0}#senate-research dt{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:#4c6177}#senate-research dd{margin:4px 0 0;font-size:15px;line-height:1.5}#senate-research .sr-links{display:flex;gap:14px;flex-wrap:wrap;margin:16px 0;font-size:14px}#senate-research a{overflow-wrap:anywhere;color:#215790}#senate-research .sr-table-wrap{overflow-x:auto;border:1px solid #d0dce8;border-radius:10px;margin-top:16px}#senate-research table{width:100%;min-width:700px;border-collapse:collapse;font-size:14px;background:#fff}#senate-research th,#senate-research td{text-align:left;vertical-align:top;padding:12px;border-bottom:1px solid #dce5ee}#senate-research th{background:#eff4f9;color:#182c47}#senate-research caption{text-align:left;padding:14px;font-weight:700}#senate-research .sr-small-head{margin-top:26px}#senate-research summary{min-height:44px;cursor:pointer;font-weight:700;padding:12px 0}#senate-research .sr-sources{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:18px}#senate-research .sr-source{border-top:1px solid #ccd9e5;padding-top:12px;font-size:14px;min-width:0}#senate-research .sr-source p{margin:5px 0}#senate-research :focus-visible{outline:3px solid #a75500;outline-offset:3px}#senate-research .sr-archive{font-weight:700}#senate-research .sr-result{font-size:18px;font-weight:700;color:#173e65;margin:20px 0 10px}#senate-research .sr-header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}#senate-research .sr-date{flex:none;text-align:right;font-size:13px;color:#4c6177;padding-top:7px}
@media(max-width:760px){#senate-research .sr-grid,#senate-research .sr-sources{grid-template-columns:1fr}#senate-research .sr-card{padding:18px}#senate-research .sr-tabs{gap:6px}#senate-research .sr-tabs button{flex:1 1 100px;padding:10px 8px;font-size:13px}#senate-research .sr-header{display:block}#senate-research .sr-date{text-align:left}#senate-research .sr-bar-label{font-size:15px}}
@media print{#senate-research .sr-tabs,#senate-research .sr-download{display:none}#senate-research .sr-card{break-inside:avoid}#senate-research .sr-table-wrap{overflow:visible}#senate-research table{min-width:0}}
`;
  document.head.append(style);
  const $ = id => document.getElementById(id);
  let data;
  function validate(d) {
    const need = (ok, message) => { if (!ok) throw new Error(message); };
    need(d.schema_version === 1 && d.reviewed_date === '2026-11-01', 'Unexpected research version');
    need(Array.isArray(d.polls) && d.polls.length === 3, 'Poll collection incomplete');
    need(Array.isArray(d.national_context) && d.national_context.length === 2, 'National context incomplete');
    need(Array.isArray(d.sources) && d.sources.length > 0, 'Sources missing');
    const ids = new Set(d.sources.map(s => s.id));
    need(ids.size === d.sources.length, 'Duplicate sources');
    for (const s of d.sources) need(new URL(s.url).protocol === 'https:', 'Invalid source URL');
    for (const p of d.polls) {
      need(p.campaign_sponsored === true && p.measure === 'Initial ballot preference', 'Unexpected poll type');
      need([p.davis,p.letlow,p.uncommitted].every(n => Number.isFinite(n) && n >= 0 && n <= 100), 'Invalid percentage');
      need(p.davis + p.letlow + p.uncommitted === 100, 'Poll categories do not reconcile');
      need(p.field_start <= p.field_end && p.field_end <= d.reviewed_date, 'Invalid field dates');
      need(Number.isSafeInteger(p.sample_n) && p.sample_n > 0 && ids.has(p.source_id), 'Missing poll metadata');
    }
    for (const p of d.national_context) need(ids.has(p.source_id) && [p.democratic,p.republican].every(n => Number.isFinite(n) && n >= 0 && n <= 100), 'Invalid national context');
    for (const r of d.national_race_assessments) need(ids.has(r.source_id), 'Missing assessment source');
    return d;
  }
  function source(id) { return data.sources.find(s => s.id === id); }
  function sourceLink(id, label) { const s = source(id); return link(s.url, label || s.label); }
  function bars(rows) {
    return rows.map(([name,value,cls]) => `<div class="sr-bar"><div class="sr-bar-label"><span>${esc(name)}</span><strong>${value}%</strong></div><div class="sr-track" aria-hidden="true"><span class="sr-fill ${cls}" style="width:${value}%"></span></div></div>`).join('') + '<div class="sr-axis" aria-hidden="true"><span>0%</span><span>50%</span><span>100%</span></div>';
  }
  function renderPoll(id) {
    const p = data.polls.find(p => p.id === id); if (!p) return;
    const margin = p.letlow - p.davis;
    const result = margin === 0 ? 'Equal reported support in this sample' : (margin > 0 ? 'Letlow' : 'Davis') + ' ahead by ' + Math.abs(margin) + ' percentage points in this sample';
    $('senate-poll-chart').innerHTML = `<span class="sr-badge sr-sponsor">Davis campaign commissioned</span><h3>${esc(p.pollster)}</h3><p class="sr-fine">Interviews: ${esc(period(p))}</p>${bars([['Jamie Davis (Democrat)',p.davis,'sr-dem'],['Julia Letlow (Republican)',p.letlow,'sr-rep'],[p.uncommitted_label,p.uncommitted,'sr-other']])}<p class="sr-result">${esc(result)}</p><p class="sr-fine">Initial ballot preference. Percentages are shares of survey responses, not recorded ballots or chances of winning.</p><div class="sr-links">${sourceLink(p.source_id, p.id === 'ppp_july' ? 'Read the documented reporting' : 'Read the original pollster memo')}</div>`;
    const rows = [['Population',p.population],['Sample',p.sample_n.toLocaleString('en-US') + ' respondents'],['Sponsor',p.sponsor],['Reported margin of error',p.moe_percentage_points === null ? 'Not supplied in the reviewed source' : '±' + p.moe_percentage_points + ' percentage points'],['Method',p.mode],['Memo or source date',date(p.published_date)],['Date meaning',p.publication_basis],['Evidence status',p.evidence]];
    $('senate-poll-meta').innerHTML = '<h3>Read this survey correctly</h3><dl class="sr-meta">' + rows.map(([k,v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('') + '</dl><p class="sr-fine">' + esc(p.limitations) + '</p>';
    $('senate-selection-status').textContent = p.pollster + '. ' + period(p) + '. Davis ' + p.davis + '%, Letlow ' + p.letlow + '%, ' + p.uncommitted_label.toLowerCase() + ' ' + p.uncommitted + '%.';
  }
  function render() {
    section.innerHTML = `<div class="sr-header"><div><p class="eyebrow">03A / SENATE SURVEY RESEARCH</p><h2 id="senate-title">Louisiana’s U.S. Senate race</h2></div><p class="sr-date">Research checked ${date(data.reviewed_date)}<br>Latest Louisiana field date: October 29</p></div>
<p class="section-intro"><strong>Jamie Davis (Democrat) and Julia Letlow (Republican).</strong> Statewide general election on November 3, 2026. ${sourceLink('sos_candidates','Official candidate listing')}.</p>
<p class="sr-fine">Louisiana polls, national surveys and national race assessments answer different questions. Explore them separately.</p>
<div class="sr-callout sr-warning"><p><strong>Three surveys. Two firms. One campaign sponsor.</strong> All three Louisiana surveys located were commissioned by Davis’s campaign. No independently sponsored Louisiana general election poll was located in this review.</p></div>
<p class="sr-archive sr-fine" id="senate-archive" hidden>Archived research for the November 3, 2026 election. These are survey snapshots, not election results.</p>
<div class="sr-tabs" role="tablist" aria-label="Senate research views">${[['louisiana','Louisiana polls'],['national','National context'],['sources','Sources and limits']].map(([id,label],i) => `<button class="sr-button" type="button" role="tab" id="sr-tab-${id}" aria-selected="${i===0}" aria-controls="sr-panel-${id}" tabindex="${i===0?0:-1}">${label}</button>`).join('')}</div>
<div id="sr-panel-louisiana" role="tabpanel" aria-labelledby="sr-tab-louisiana"><label for="senate-poll-select">Choose a Louisiana survey</label><select id="senate-poll-select">${data.polls.map(p => `<option value="${esc(p.id)}">${esc(p.pollster)} | ${esc(period(p))}</option>`).join('')}</select><div class="sr-grid"><article id="senate-poll-chart" class="sr-card"></article><aside id="senate-poll-meta" class="sr-card sr-subtle"></aside></div><p id="senate-selection-status" class="sr-fine" role="status" aria-live="polite"></p>
<details><summary>Compare the three initial ballot snapshots</summary><div class="sr-table-wrap" tabindex="0" role="region" aria-label="Scrollable Louisiana poll comparison"><table><caption>Initial preferences only. Different dates and voter screens.</caption><thead><tr><th scope="col">Survey</th><th scope="col">Field dates</th><th scope="col">Sample</th><th scope="col">Davis</th><th scope="col">Letlow</th><th scope="col">Not sure or undecided</th><th scope="col">Evidence</th></tr></thead><tbody>${data.polls.map(p=>`<tr><th scope="row">${esc(p.pollster)}</th><td>${esc(period(p))}</td><td>${p.sample_n}<br>${esc(p.population)}</td><td>${p.davis}%</td><td>${p.letlow}%</td><td>${p.uncommitted}%</td><td>${sourceLink(p.source_id,p.id==='ppp_july'?'News report':'Pollster memo')}</td></tr>`).join('')}</tbody></table></div></details>
<div class="sr-callout"><p><strong>Separate surveys, not a polling average.</strong> These are separate snapshots. Campaign sponsorship, different voter screens and limited documentation prevent a confident claim that the underlying race moved by the difference between published numbers. A tied sample is not a prediction of a tied election.</p></div></div>
<div id="sr-panel-national" role="tabpanel" aria-labelledby="sr-tab-national" hidden><div class="sr-callout"><p><strong>National context is not a Louisiana Senate poll.</strong> These surveys ask about congressional party preference nationwide. They do not measure support for Davis or Letlow, and they cannot be converted into Louisiana vote shares or Senate seats.</p></div><div class="sr-grid">${data.national_context.map(p=>`<article class="sr-card"><span class="sr-badge">National generic congressional ballot</span><h3>${esc(p.pollster)}</h3><p class="sr-fine">Interviews: ${esc(period(p))}<br>Release: ${date(p.published_date)}</p>${bars([['Democratic candidate',p.democratic,'sr-dem'],['Republican candidate',p.republican,'sr-rep']])}<p class="sr-fine">${esc(p.sample_note)}.</p><p class="sr-fine">${esc(p.uncertainty)}. ${esc(p.mode)}.</p><p class="sr-fine">${esc(p.note)}</p><div class="sr-links">${sourceLink(p.source_id,'Read the pollster release')}${p.id==='marist_national'?sourceLink('marist_tables','Methodology and tables'):''}</div></article>`).join('')}</div>
<h3 class="sr-small-head">How national analysts classify Louisiana</h3><p class="sr-fine">Ratings and forecasts are assessments, not additional polls. A close campaign survey and a Republican leaning assessment can coexist because the assessments use other evidence.</p><div class="sr-grid">${data.national_race_assessments.map(r=>`<article class="sr-card sr-subtle"><span class="sr-badge">${esc(r.kind)}</span><h3>${esc(r.publisher)}</h3><p class="sr-result">${esc(r.assessment)}</p><p class="sr-fine">${esc(r.date_note)}</p><div class="sr-links">${sourceLink(r.source_id,'View publisher assessment')}</div></article>`).join('')}</div></div>
<div id="sr-panel-sources" role="tabpanel" aria-labelledby="sr-tab-sources" hidden><div class="sr-grid"><article class="sr-card"><h3>What is included</h3><p>Three Louisiana initial ballot surveys, two national context surveys, and two national assessments of the Louisiana race. Repeated coverage of the same poll counts once.</p><p>Hart’s original October memo specifies <strong>502 respondents</strong>. That figure is used rather than the 500 mentioned in one news report. Both original Hart memos and the relevant Marist report pages were visually checked.</p><p>The July PPP entry is explicitly marked as documented reporting because the underlying report was not retrieved.</p></article><article class="sr-card sr-subtle"><h3>What is not inferred</h3><p>Candidate descriptions, followup questions pressing undecided voters, and initial preferences are not interchangeable. Only initial preferences enter the Louisiana comparison.</p><p>A poll’s reported margin of error is not the margin of error of the difference between candidates. Sampling error is also not the only source of uncertainty.</p><p>No candidate support is inferred from early voting counts, race, party registration, parish location or the participation calculator. No national result is assigned to Louisiana.</p></article></div><div class="sr-links sr-download"><button type="button" class="sr-button" id="senate-download">Download research JSON</button><a class="sr-button" href="docs/SENATE_POLLING_20261101.md">Read the research record</a></div><p class="sr-fine">Reviewed ${date(data.reviewed_date)}. Sources retain their own dates and terms. Documentation is not an independent audit of polling quality.</p><div class="sr-sources">${data.sources.map(s=>`<article class="sr-source">${link(s.url,s.label)}<p class="sr-fine">${esc(s.type)}${s.locator?'. '+esc(s.locator):''}.</p></article>`).join('')}</div></div>
<p class="sr-fine">Dated research, not a live feed. Surveys are not ballots. Tiandra Fields | Provisional Consulting LLC.</p>`;
    renderPoll(data.polls[0].id);
    $('senate-poll-select').addEventListener('change',e=>renderPoll(e.target.value));
    const kinds=['louisiana','national','sources'];
    function tab(kind){for(const k of kinds){const active=k===kind;$('sr-tab-'+k).setAttribute('aria-selected',String(active));$('sr-tab-'+k).tabIndex=active?0:-1;$('sr-panel-'+k).hidden=!active;}}
    for(const kind of kinds){$('sr-tab-'+kind).addEventListener('click',()=>tab(kind));$('sr-tab-'+kind).addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=kinds.indexOf(kind),next=e.key==='Home'?kinds[0]:e.key==='End'?kinds[2]:kinds[(i+(e.key==='ArrowRight'?1:2))%3];tab(next);$('sr-tab-'+next).focus();});}
    $('senate-download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='Louisiana_Senate_Research_20261101.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);});
    const archive=()=>{$('senate-archive').hidden=Date.now()<=Date.parse('2026-11-04T02:00:00Z');};archive();window.addEventListener('pageshow',archive);
    section.dataset.ready='true';
    if(location.hash==='#senate-research')requestAnimationFrame(()=>section.scrollIntoView());
  }
  const nav=document.querySelector('.nav-inner'), old=nav&&nav.querySelector('a[href="#polling-research"]');
  if(old){const a=document.createElement('a');a.href='#senate-research';a.textContent='Senate polling';old.before(a);old.textContent='District 6 polls';}
  const eyebrow=target.querySelector('.eyebrow');if(eyebrow)eyebrow.textContent='03B / DISTRICT 6 SURVEY RESEARCH';
  fetch('data/processed/polling_senate_2026-11-01.json?v=20261101-senate1',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('Research unavailable');return r.json();}).then(d=>{data=validate(d);render();}).catch(()=>{
    $('senate-status').innerHTML='The research collection could not be loaded. The rest of the dashboard remains available. '+link('https://cms.bayouprogressive.com/wp-content/uploads/2026/10/10.30-Poll-memo.pdf','Read the October Hart memo')+' or '+link('https://maristpoll.marist.edu/polls/u-s-midterm-elections-october-2026/','read national polling context')+'.';section.dataset.ready='error';
  });
})();
